<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();$customerId=(int)$_SESSION['customer_id'];$id=(int)($_GET['id']??0);
$st=$db->prepare("SELECT o.*,i.name item_name,i.image_path,v.store_name FROM orders o JOIN items i ON i.id=o.item_id JOIN vendors v ON v.id=o.vendor_id WHERE o.id=? AND o.customer_id=?");$st->execute([$id,$customerId]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Rental order not found.');}
$st=$db->prepare("SELECT inspection_type,condition_score,created_at FROM condition_reports WHERE rental_order_id=? ORDER BY created_at DESC");$st->execute([$id]);$reports=[];foreach($st->fetchAll() as $r){if(!isset($reports[$r['inspection_type']]))$reports[$r['inspection_type']]=$r;}
$st=$db->prepare("SELECT status,completed_at,created_at FROM sanitization_records WHERE rental_order_id=? ORDER BY created_at DESC LIMIT 1");$st->execute([$id]);$san=$st->fetch();
$stages=['new'=>'Booking confirmed','in_progress'=>'Pickup / active rental','completed'=>'Returned'];$current=$o['status']==='completed'?4:($o['status']==='in_progress'?2:1);if($o['status']==='completed'&&isset($reports['after_return'])&&$san&&$san['status']==='completed')$current=6;
$timeline=[['Booking confirmed',1,'Order placed and recorded'],['Pickup / handover',2,'Vendor has moved the rental into its active stage'],['Active rental',3,'Keep the attire until the stated return date'],['Return received',4,'Return is recorded when the rental is completed'],['Inspection',5,'After-return condition inspection'],['Sanitization',6,'Cleaning/sanitization record completion']];
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rental Tracking</title><style>body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;text-decoration:none;margin-left:18px}.main{max-width:850px;margin:auto;padding:30px}.card{background:#fff;border:1px solid #E8E0D0;padding:22px;margin-bottom:18px}.hero{background:#21170B;color:#fff}.stage{display:flex;gap:15px;padding:16px 0;border-bottom:1px solid #eee}.dot{width:28px;height:28px;border-radius:50%;background:#ddd;display:flex;align-items:center;justify-content:center;flex:none}.done .dot{background:#C9A84C}.done b{color:#3D2B0F}.muted{color:#888}.small{font-size:12px;color:#777;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{border:1px solid #E8E0D0;padding:14px}.ok{color:#166534;font-weight:bold}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="orders.php">← My Orders</a><a href="home.php">Home</a></div><main class="main"><section class="card hero"><h1>📦 Rental Tracking #<?=str_pad($o['id'],6,'0',STR_PAD_LEFT)?></h1><p><?=htmlspecialchars($o['item_name'])?> · <?=htmlspecialchars($o['store_name'])?></p></section><section class="card"><h2>Rental lifecycle</h2><?php foreach($timeline as $i=>$t):$done=$current>=$t[1];?><div class="stage <?=$done?'done':''?>"><div class="dot"><?=$done?'✓':$t[1]?></div><div><b><?=htmlspecialchars($t[0])?></b><div class="small"><?=htmlspecialchars($t[2])?></div></div></div><?php endforeach;?></section><section class="card"><h2>Rental details</h2><div class="grid"><div class="box">Pickup<br><b><?=date('d M Y',strtotime($o['pickup_date']))?></b></div><div class="box">Return due<br><b><?=date('d M Y',strtotime($o['return_date']))?></b></div><div class="box">Status<br><b><?=htmlspecialchars(ucwords(str_replace('_',' ',$o['status'])))?></b></div><div class="box">Rental<br><b>₹<?=number_format((float)$o['total_rent'],2)?></b></div><div class="box">Security deposit<br><b>₹<?=number_format((float)$o['security_deposit'],2)?></b></div><div class="box">Delivery<br><b>₹<?=number_format((float)$o['delivery_charge'],2)?></b></div><div class="box">Final total<br><b>₹<?=number_format((float)$o['final_total'],2)?></b></div></div></section><section class="card"><h2>Trust & return checks</h2><div class="grid"><div class="box">Before-rental inspection<?php if(isset($reports['before_rental'])):?><div class="ok">✓ <?=number_format((float)$reports['before_rental']['condition_score'],1)?>/100</div><div class="small"><?=date('d M Y',strtotime($reports['before_rental']['created_at']))?></div><?php else:?><div class="muted">Not recorded</div><?php endif;?></div><div class="box">After-return inspection<?php if(isset($reports['after_return'])):?><div class="ok">✓ <?=number_format((float)$reports['after_return']['condition_score'],1)?>/100</div><div class="small"><?=date('d M Y',strtotime($reports['after_return']['created_at']))?></div><?php else:?><div class="muted">Not recorded</div><?php endif;?></div><div class="box">Sanitization<?php if($san):?><div class="<?=($san['status']==='completed'?'ok':'')?>"><?=htmlspecialchars(ucwords(str_replace('_',' ',$san['status'])))?></div><?php else:?><div class="muted">Not recorded</div><?php endif;?></div></div><p class="small">The refundable security deposit is shown separately from rental revenue. Any late charges are added after return. Condition and sanitization records are vendor-entered operational records; they are not independent certification.</p></section></main></body></html>